import { test } from "node:test";
import assert from "node:assert/strict";
import { createSheet, setCell } from "../src/sheet.mjs";
import { valueOf, computeAll, dependents } from "../src/recalc.mjs";

test("valueOf reads raw text", () => {
  assert.equal(valueOf(""), null);
  assert.equal(valueOf(" 4.5 "), 4.5);
  assert.equal(valueOf("tRuE"), true);
  assert.equal(valueOf("'=x"), "=x");
  assert.equal(valueOf("Infinity"), "Infinity");
});

test("computeAll handles long chains, cycles and bad formulas", () => {
  const s = createSheet();
  setCell(s, "A1", "1");
  for (let r = 2; r <= 10000; r++) setCell(s, `A${r}`, `=A${r - 1}+1`);
  setCell(s, "C1", "=C1");
  setCell(s, "C2", "=C1+1");
  setCell(s, "D1", "=(");
  const v = computeAll(s);
  assert.equal(v.get("A10000"), 10000);
  assert.equal(v.get("C1"), "#CYCLE!");
  assert.equal(v.get("C2"), "#CYCLE!");
  assert.equal(v.get("D1"), "#ERROR!");
});

test("dependents lists readers in dependency order, by row then column", () => {
  const s = createSheet();
  setCell(s, "A1", "1");
  setCell(s, "B1", "=A1");
  setCell(s, "A2", "=A1*2");
  setCell(s, "C3", "=B1+A2");
  setCell(s, "D1", "=A1");
  assert.deepEqual(dependents(s, "A1"), ["A2", "B1", "D1", "C3"]);
});
