// Minimal mock for local testing only: numbers, refs, + - * and parentheses.
const tokenize = (t) => {
  const out = [];
  const re = /\s*(\$?[A-Za-z]+\$?\d+|\d+(\.\d+)?|[-+*()])/y;
  let m; let pos = 0;
  while (pos < t.length) {
    re.lastIndex = pos;
    m = re.exec(t);
    if (!m) { if (/^\s*$/.test(t.slice(pos))) break; throw new Error("bad"); }
    out.push(m[1]); pos = re.lastIndex;
  }
  return out;
};
export function parseFormula(text) {
  const toks = tokenize(text); let i = 0;
  const peek = () => toks[i];
  const expr = () => { let n = term(); while (peek() === "+" || peek() === "-") { const op = toks[i++]; n = { op, a: n, b: term() }; } return n; };
  const term = () => { let n = factor(); while (peek() === "*") { i++; n = { op: "*", a: n, b: factor() }; } return n; };
  const factor = () => {
    const t = toks[i++];
    if (t === undefined) throw new Error("eof");
    if (t === "(") { const n = expr(); if (toks[i++] !== ")") throw new Error("paren"); return n; }
    if (/^\d/.test(t)) return { num: Number(t) };
    if (/^\$?[A-Za-z]/.test(t)) return { ref: t.replace(/\$/g, "").toUpperCase() };
    throw new Error("unexpected " + t);
  };
  const ast = expr();
  if (i !== toks.length) throw new Error("trailing");
  return ast;
}
export function refsOf(ast) {
  if (ast.ref) return [ast.ref];
  if (ast.num !== undefined) return [];
  return [...refsOf(ast.a), ...refsOf(ast.b)];
}
export function evaluate(ast, lookup) {
  if (ast.num !== undefined) return ast.num;
  if (ast.ref) { const v = lookup(ast.ref); if (typeof v === "string" && v.startsWith("#")) return v; return v ?? 0; }
  const a = evaluate(ast.a, lookup), b = evaluate(ast.b, lookup);
  if (typeof a === "string") return a;
  if (typeof b === "string") return b;
  return ast.op === "+" ? a + b : ast.op === "-" ? a - b : a * b;
}
